const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const fireLocation = ee.Geometry.Point([-125.0, 52.5]); // Itcha Lake, BC
  const usPNW = ee.Geometry.Polygon([
    [[-125, 49], [-125, 42], [-116, 42], [-116, 49], [-125, 49]]
  ]); // US Pacific Northwest (south of Canadian border)

  const date = '2025-09-02';
  const dateStart = '2025-09-01';
  const dateEnd = '2025-09-03';

  // 2. Data Acquisition - Sentinel-5P Aerosol Index
  let aerosolCol = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_AER_AI')
    .filterDate(dateStart, dateEnd)
    .filterBounds(fireLocation.buffer(500000)); // 500km buffer around fire

  console.log('Aerosol images found:', aerosolCol.size().getInfo());

  if (aerosolCol.size().getInfo() === 0) {
    console.log('No Sentinel-5P data available. Trying MODIS Terra AOD...');

    aerosolCol = ee.ImageCollection('MODIS/061/MOD08_D3')
      .filterDate(dateStart, dateEnd)
      .select('Aerosol_Optical_Depth_Land_Mean');

    console.log('MODIS images found:', aerosolCol.size().getInfo());

    if (aerosolCol.size().getInfo() === 0) {
      console.log('No aerosol data available for the date.');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 3. Processing - Get aerosol values
  const aerosolImg = aerosolCol.mean();
  const bandName = aerosolCol.first().bandNames().getInfo()[0];

  // Check aerosol levels near fire source
  const fireAerosol = aerosolImg.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: fireLocation.buffer(50000),
    scale: 5000,
    maxPixels: 1e9
  }).get(bandName);

  const fireAerosolVal = fireAerosol.getInfo();

  // Check aerosol levels in US PNW
  const pnwAerosol = aerosolImg.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: usPNW,
    scale: 5000,
    maxPixels: 1e9
  }).get(bandName);

  const pnwAerosolVal = pnwAerosol.getInfo();

  // Count valid pixels in US PNW
  const pnwPixelCount = aerosolImg.select(bandName).reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: usPNW,
    scale: 5000,
    maxPixels: 1e9
  }).get(bandName);

  const pnwPixels = pnwPixelCount.getInfo();

  console.log(`Fire area aerosol (${bandName}):`, fireAerosolVal);
  console.log(`US PNW aerosol (${bandName}):`, pnwAerosolVal);
  console.log('Valid pixels in US PNW:', pnwPixels);

  // 4. Validation & Answer
  if (pnwPixels === 0) {
    console.log('No valid aerosol data over US Pacific Northwest.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (pnwAerosolVal === null || fireAerosolVal === null) {
    console.log('Calculation returned null values.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Determine if smoke spread south
  // For Sentinel-5P AER_AI: values > 1 indicate elevated aerosols/smoke
  // For MODIS AOD: values > 0.3 indicate elevated aerosols
  const threshold = bandName.includes('AER_AI') ? 1.0 : 0.3;

  if (pnwAerosolVal > threshold && fireAerosolVal > threshold) {
    console.log(`Elevated aerosols detected in both fire area and US PNW (threshold: ${threshold}).`);
    console.log('<answer>A</answer>');
  } else {
    console.log(`No significant smoke spread to US PNW detected (PNW: ${pnwAerosolVal.toFixed(3)}, threshold: ${threshold}).`);
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
